// Normaliza payloads de Evolution API y del formulario web
const body = $input.first().json.body || $input.first().json;

let from = '';
let message = '';
let pushName = '';
let source = 'unknown';

// --- Evolution API ---
if (body.data && body.data.key) {
  // Ignorar mensajes que envía el propio bot
  if (body.data.key.fromMe === true) {
    return [{ json: { skip: true, reason: 'mensaje propio' } }];
  }
  from = body.data.key.remoteJid.replace('@s.whatsapp.net', '');
  message = body.data.message?.conversation
    || body.data.message?.extendedTextMessage?.text
    || '';
  pushName = body.data.pushName || '';
  source = 'whatsapp';
}
// --- Formulario / chat web ---
else if (body.source === 'web-form' || body.source === 'web-chat') {
  from = (body.telefono || body.sessionId || 'anon').replace(/\D/g, '') || body.telefono;
  if (from && from.length < 10 && !from.startsWith('web_')) {
    from = 'web_' + from;
  }
  message = body.mensaje || body.message || '';
  pushName = body.nombre || 'Visitante web';
  source = 'web';
}

if (!message || !from) {
  return [{ json: { skip: true, reason: 'datos faltantes' } }];
}

return [{
  json: {
    from,
    message: message.trim(),
    pushName,
    source
  }
}];

// Detecta si la respuesta es texto normal o una tool call
const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';

if (!content) {
  return [{ json: { type: 'text', text: 'Disculpa, hubo un problema. ¿Puedes repetir?' } }];
}

// Intenta parsear como JSON tool call
const trimmed = content.trim();
if (trimmed.startsWith('{') && trimmed.includes('"tool"')) {
  try {
    // Extrae el primer objeto JSON válido
    const match = trimmed.match(/\{[\s\S]*?\}(?=\s*$|\s*[^,])/);
    const jsonStr = match ? match[0] : trimmed;
    const parsed = JSON.parse(jsonStr);

    if (parsed.tool && parsed.args) {
      return [{
        json: {
          type: 'tool_call',
          toolName: parsed.tool,
          toolArgs: parsed.args
        }
      }];
    }
  } catch(e) {
    // No era JSON válido, lo tratamos como texto
  }
}

return [{ json: { type: 'text', text: content } }];

const events = $input.all();
const libre = events.length === 0 || !events[0].json.id;
const args = $('Parsear respuesta').first().json.toolArgs;

const horaTxt = args.hora;
const fechaTxt = new Date(args.fecha + 'T00:00:00-05:00').toLocaleDateString('es-CO',
  { weekday:'long', day:'numeric', month:'long', timeZone:'America/Bogota' });

const respuesta = libre
  ? `¡Perfecto! El *${fechaTxt}* a las *${horaTxt}* está disponible ✅\n\nPara reservarte necesito algunos datos. ¿Me compartes tu *nombre completo*?`
  : `Esa franja ya está reservada 😕 ¿Te sirve una hora más temprano o más tarde el mismo día? También puedo proponerte el día siguiente a la misma hora.`;

return [{ json: { texto: respuesta } }];

const args = $('Parsear respuesta').first().json.toolArgs;
const fechaTxt = new Date(args.fecha + 'T00:00:00-05:00').toLocaleDateString('es-CO',
  { weekday:'long', day:'numeric', month:'long', timeZone:'America/Bogota' });
const total = (args.total || args.sueros.reduce((s,x)=>s+(x.precio||0)*x.cantidad,0)).toLocaleString('es-CO');

const texto = `¡Listo, ${args.nombre.split(' ')[0]}! 🎉

*Tu cita está confirmada* ✅

📅 ${fechaTxt}
⏰ ${args.hora}
📍 ${args.direccion}, ${args.barrio}
💧 ${args.sueros.map(s => s.nombre + (s.cantidad>1?' x'+s.cantidad:'')).join(', ')}
💰 Total: $${total}

Te enviaremos un recordatorio una hora antes. ¿Algo más en lo que pueda ayudarte?`;

return [{ json: { texto } }];

const motivo = $('Parsear respuesta').first().json.toolArgs.motivo;
const texto = `Te paso con una persona de nuestro equipo en breve 🤝\n\nMientras tanto, si es urgente puedes llamarnos al *+57 322 562 5668*.`;
return [{ json: { texto, motivo } }];

// Unifica todas las ramas en un solo nodo de envío
const items = $input.all();
const texto = items[0].json.texto || items[0].json.text || 'Disculpa, hubo un problema. ¿Puedes repetir?';
const from = $('Normalizar entrada').first().json.from;
const source = $('Normalizar entrada').first().json.source;
return [{ json: { texto, from, source } }];
